package com.vynedam.stockai.service;
import com.vynedam.stockai.dto.WarehouseDtos.*; import com.vynedam.stockai.exception.ApiException; import com.vynedam.stockai.model.*; import com.vynedam.stockai.repository.*; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service;
@Service public class WarehouseService { private final WarehouseRepository warehouses;private final UserRepository users;public WarehouseService(WarehouseRepository w,UserRepository u){warehouses=w;users=u;}public List<Warehouse>list(){return warehouses.findAll();}public Warehouse get(String id){return warehouses.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"NOT_FOUND","Warehouse not found"));}public Warehouse create(WarehouseRequest r){var w=new Warehouse();w.code=nextCode();apply(w,r);return warehouses.save(w);}public Warehouse update(String id,WarehouseRequest r){var w=get(id);apply(w,r);return warehouses.save(w);}public Warehouse setActive(String id,boolean active){var w=get(id);w.active=active;return warehouses.save(w);}public void assignStaff(String warehouseId,StaffAssignmentRequest r){get(warehouseId);var assigned=new HashSet<>(r.userIds());for(var userId:assigned){var u=users.findById(userId).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"NOT_FOUND","User not found: "+userId));u.warehouseIds.add(warehouseId);users.save(u);}for(var u:users.findAll()){if(!assigned.contains(u.id)&&u.warehouseIds.remove(warehouseId))users.save(u);}}public void assertOperationalAccess(String warehouseId,String userId){var w=get(warehouseId);if(!w.active)throw new ApiException(HttpStatus.CONFLICT,"WAREHOUSE_INACTIVE","Warehouse is inactive");var u=users.findById(userId).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"UNAUTHENTICATED","User no longer exists"));if(u.role.name().equals("SUPER_ADMIN")||u.role.name().equals("PLANT_MANAGER"))return;if(!u.warehouseIds.contains(warehouseId))throw new ApiException(HttpStatus.FORBIDDEN,"WAREHOUSE_ACCESS_DENIED","User is not assigned to this warehouse");}private String nextCode(){String code;do{code="WH-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();}while(warehouses.existsByCode(code));return code;}private void apply(Warehouse w,WarehouseRequest r){w.name=r.name().trim();w.unitId=r.unitId().trim();w.type=r.type().trim().toUpperCase();w.address=r.address();w.capacity=r.capacity()==null?0:r.capacity();w.capacityUnit=r.capacityUnit()==null?"KG":r.capacityUnit().trim().toUpperCase();}}
